head.script:
///////// 1. 변수 및 선언 영역 /////////
// 원본 : ULDBNS30300.gfm (채권 마감관리 > 채권상장마감)
/*
 * 화면 동작
 *  - [상장마감] 탭: 화면을 열면 마감일 정보(현재일·적용일)를 받아 전송내역·마감 상태·시장조치별 종목수를 조회하고,
 *    첫 시장조치의 종목정보(조치내역)를 보여 준다. [시장조치내역생성] → [상장마감] 순서로 처리하고, 운영자는 [재마감처리]로 되돌린다.
 *  - [상장마감내역] 탭: 업무마감일로 마감된 시장조치별 종목수·전송내역·전송정보를 조회하고, 시장지파일·종목상세 팝업을 연다.
 *  - 원본의 processGp(1 마감전·2 마감내역·3 생성·4 마감·9 재마감) 전역 상태는 쓰지 않는다 — 탭마다 DataCollection 을 따로 두고
 *    처리 흐름을 함수로 나눴다(결과서 §8 #1).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDBNS30300/ULDBNS30300.md (§번호는 이 문서의 절)
 */

scwin.endClsDd = "";    // [상장마감내역] 조회 기준일 — 마감일 조회 응답 endClsDd (원본 dts_CheckCls END_CLS_DD, §6.2)

// [상장마감] 마감 상태 문구 (원본 dts_CheckCls OnLoadCompleted 의 txb_ClsDtl — §7.2)
scwin.CLS_DTL_MSG = {
    done : "* 마감처리 완료",
    notDone : "* \"상장마감\"이 완료되지 않았습니다. 상장마감 시 \"시장조치내역생성\" 후 \"상장마감\" 하시기 바랍니다."
};

// [상장마감] 조치내역 종목정보 그리드에서 시장조치코드별로 켜고 끄는 열 (원본 fn_showFalse 의 대상 — §6.3)
scwin.ISU_TOGGLE_COLS = ["bndApplId", "stdCd", "isurNm", "isuNm", "isuAmt", "isuDd", "listDd", "redmptDd", "bfIsuNm", "afIsuNm",
    "tpNm", "bfListAmt", "afListAmt", "chgListDtl", "exerAmt", "bwIsuNm", "geIsuNm", "bwListAmt", "geListAmt", "redmptAmt",
    "addListAmt", "bfExerPrc", "afExerPrc", "bfIsurPrc", "afIsurPrc", "chgRsnContn", "bfCoupnRt", "afCoupnRt", "bfRedmptDd", "afRedmptDd",
    "bfFstDd", "afFstDd", "delistRsnContn", "delistDd", "bfStripNsprtBal", "sprtParAmt", "recombinParAmt", "afStripNsprtBal", "bfCredit", "afCredit",
    "strtDdWit", "splitRedmptDd", "chgSplitRedmptDd", "bkHoldyPrincPayDdDecsnNm", "indexNm"];

// 시장조치코드 → 보이는 열 (원본 fn_IntiIsuCol 분기 + fn_show* — §6.3, §7.1). 표에 없는 코드는 default(신규상장 111·121·131·141·151 등)
scwin.ISU_COLS_BY_MKT = {
    "201" : ["bndApplId", "stdCd", "isurNm", "bfIsuNm", "afIsuNm"],                                        // 상호변경
    "202" : ["bndApplId", "tpNm", "stdCd", "isurNm", "bfIsuNm", "afIsuNm"],                                // 합병/회사분할
    "203" : ["bndApplId", "tpNm", "stdCd", "isurNm", "bfIsuNm", "afIsuNm"],                                // 종목분할 (원본 fn_show202)
    "105" : ["bndApplId", "tpNm", "stdCd", "isurNm", "bfIsuNm", "afIsuNm", "bfListAmt", "afListAmt"],      // 변경상장종목분할
    "205" : ["bndApplId", "isurNm", "chgListDtl", "exerAmt"],                                              // BW 신주인수권행사
    "104" : ["bndApplId", "bwIsuNm", "geIsuNm", "bwListAmt", "geListAmt"],                                 // BW 분리종목
    "301" : ["bndApplId", "stdCd", "isuNm", "bfListAmt", "afListAmt"],                                     // 일괄상장채권 상장금액조정(월별)
    "320" : ["bndApplId", "stdCd", "isuNm", "bfListAmt", "afListAmt"],                                     // 일괄상장채권 상장금액조정(일별)
    "302" : ["bndApplId", "stdCd", "isuNm", "bfListAmt", "exerAmt", "afListAmt"],                          // 주식관련사채 권리행사
    "303" : ["bndApplId", "stdCd", "isuNm", "bfListAmt", "afListAmt"],                                     // 중도상환
    "304" : ["bndApplId", "stdCd", "isuNm", "bfListAmt", "afListAmt"],                                     // 중도상환
    "305" : ["bndApplId", "stdCd", "isuNm", "bfListAmt", "addListAmt", "afListAmt"],                       // 국고채추가발행
    "306" : ["bndApplId", "stdCd", "isuNm", "bfExerPrc", "afExerPrc", "chgRsnContn"],                      // 권리행사가액 변경
    "307" : ["bndApplId", "stdCd", "isuNm", "bfIsurPrc", "afIsurPrc"],                                     // 발행가액 변경
    "308" : ["bndApplId", "stdCd", "isuNm", "bfCoupnRt", "afCoupnRt"],                                     // 표면이자율 변경
    "309" : ["bndApplId", "stdCd", "isuNm", "bfCoupnRt", "afCoupnRt"],                                     // FRN 변동금리 변경
    "311" : ["bndApplId", "stdCd", "isuNm", "bfRedmptDd", "afRedmptDd", "bfFstDd", "afFstDd"],             // 옵션상환일 변경
    "314" : ["bndApplId", "stdCd", "isuNm", "delistDd", "delistRsnContn"],                                 // 수동상장폐지
    "315" : ["bndApplId", "stdCd", "isuNm", "isuAmt", "isuDd", "listDd", "redmptDd"],                      // BW(일반사채) 권리행사
    "316" : ["bndApplId", "stdCd", "isuNm", "isuAmt", "isuDd", "listDd", "redmptDd"],                      // 기타변경
    "500" : ["stdCd", "isuNm", "isuDd", "listDd", "redmptDd", "splitRedmptDd", "chgSplitRedmptDd", "bkHoldyPrincPayDdDecsnNm", "indexNm"], // 분할상환정보
    "900" : ["stdCd", "isuNm", "delistDd", "redmptDd", "isuDd"],                                           // 자동상장폐지(상환일만기)
    "321" : ["bndApplId", "stdCd", "isuNm", "bfCredit", "afCredit"],                                       // 신용평가등급수신
    "401" : ["bndApplId", "stdCd", "isuNm", "tpNm", "bfStripNsprtBal", "sprtParAmt", "afStripNsprtBal"],   // 스트립신규
    "402" : ["bndApplId", "stdCd", "isuNm", "tpNm", "bfStripNsprtBal", "sprtParAmt", "recombinParAmt", "afStripNsprtBal"], // 스트립추가·재결합
    "403" : ["bndApplId", "stdCd", "isuNm", "tpNm", "bfListAmt", "addListAmt", "afListAmt", "bfStripNsprtBal", "sprtParAmt", "afStripNsprtBal"], // 추가상장 및 스트립신규
    "404" : ["bndApplId", "tpNm", "stdCd", "isuNm", "bfListAmt", "addListAmt", "afListAmt", "bfStripNsprtBal", "sprtParAmt", "recombinParAmt", "afStripNsprtBal"], // 추가상장 및 스트립추가/재결합
    "405" : ["bndApplId", "tpNm", "stdCd", "isuNm", "bfListAmt", "addListAmt", "afListAmt", "bfStripNsprtBal", "sprtParAmt", "recombinParAmt", "afStripNsprtBal"], // 스트립통합
    "113" : ["bndApplId", "stdCd", "isuNm", "isuAmt", "isuDd", "strtDdWit", "redmptDd"],                   // WIT 종목지정
    "330" : ["bndApplId", "stdCd", "isuNm", "listDd", "bfCoupnRt", "afCoupnRt"],                           // WIT 종목정보확정
    "default" : ["bndApplId", "stdCd", "isuNm", "isuAmt", "isuDd", "listDd", "redmptDd"]                   // 국채·지방채·특수채·회사채·외국채권 신규상장
};

// 머리글 기본 문구와 코드별 바꿈 (원본 fn_showFalse 의 Name 복원 + fn_show105·202·402·403·404405 — §6.3, §8 #9)
scwin.ISU_HEADER_DEFAULT = {
    isurNm : "발행기관명",
    sprtParAmt : "신청 액면금액",
    recombinParAmt : "재결합신청금액",
    bfExerPrc : "변경전행사가액(원)",
    afExerPrc : "변경후행사가액(원)",
    addListAmt : "추가상장금액"
};
scwin.ISU_HEADER_BY_MKT = {
    "105" : { isurNm : "신청기관명" },
    "202" : { isurNm : "신청기관명" },
    "203" : { isurNm : "신청기관명" },
    "402" : { sprtParAmt : "분리신청금액" },
    "403" : { addListAmt : "분리신청금액" },
    "404" : { sprtParAmt : "분리신청금액" },
    "405" : { sprtParAmt : "분리신청금액" }
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.onpageload" });
    }
};

/**
 * @method
 * @name scwin.onpageunload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 화면 언로드. 정리할 자원이 없다(원본에도 없음).
 * @returns
 * @hidden N
 */
scwin.onpageunload = function () {
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — [상장마감] 탭 조회. 탭 본문 안 컴포넌트 제어(재마감처리 버튼 권한·종목정보 열 초기화·달력/Enter 키 바인딩)는 탭 로드 때 scwin.tab_List_ontabload·scwin.tab_ListCls_ontabload 가 한다(규칙 45). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // [상장마감] 탭 조회 (원본 processGp = '1'; fn_SearchClsDd(''))
    await scwin.loadClsTab();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.tab_List_onchange
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상위 탭 전환 — [상장마감] 이면 목록을 비우고 다시 조회, [상장마감내역] 이면 시장조치별 종목수·종목정보만 비운다. (원본 tab_List OnSelChanged — §4)
 * @param {String} tabId 선택된 탭 id
 * @param {Number} index 선택된 탭 index
 * @returns
 * @hidden N
 */
scwin.tab_List_onchange = async function (tabId, index) {
    try {
        if (Number(tab_List.getSelectedTabIndex()) === 0) {
            dlt_bndListingCloseClsList.removeAll();
            dlt_bndListingCloseClsDtl.removeAll();
            await scwin.loadClsTab();
        } else {
            dlt_bndListingCloseClsEnd.removeAll();
            dlt_bndListingCloseClsEndDtl.removeAll();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.tab_List_onchange" });
    }
};

/**
 * @method
 * @name scwin.tab_List_ontabload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상위 탭 로드(탭마다 처음 그려질 때 한 번) — 로드된 탭 본문의 컴포넌트만 제어한다. [상장마감] 재마감처리 버튼 권한·달력 2개, [상장마감내역] 달력·조회 영역 Enter 키(규칙 22·37·45). 첫 탭은 scwin.init 보다 먼저 온다. (원본 gform onload — §3)
 * @param {String} tabId 엔진 탭 id ("tab_List_tab_{tabs id}")
 * @param {Number} index 로드된 탭 index
 * @param {String} userTabId w2:tabs id
 * @returns
 * @hidden N
 */
scwin.tab_List_ontabload = async function (tabId, index, userTabId) {
    try {
        if (index === 0) {
            // [상장마감] 재마감처리 버튼 — 운영자(사용자구분 1)만 (원본 js_usr_tp_cd == '1' → showObj)
            if (String($c.session.getUserInfo("usrTpCd") ?? "") === "1") {
                btn_ReClsProcs.show("");
            } else {
                btn_ReClsProcs.hide();
            }
            // 단일 달력 2개(기간 쌍 없음)
            $c.date.checkCalendarFormat(edt_PrsntDd, "yyyyMMdd");
            $c.date.checkCalendarFormat(edt_StrtDd, "yyyyMMdd");
        } else if (index === 1) {
            // [상장마감내역] 단일 달력, 조회 영역 Enter 키
            $c.date.checkCalendarFormat(edt_BizClsDd, "yyyyMMdd");
            $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.tab_List_ontabload" });
    }
};

/**
 * @method
 * @name scwin.tab_ListCls_ontabload
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 하위 탭 로드 — [조치내역] 종목정보 열을 기본(신규상장) 열로 둔다(규칙 45). (원본 fn_IntiIsuCol, vMktCd = '' — §3)
 * @param {String} tabId 엔진 탭 id ("tab_ListCls_tab_{tabs id}")
 * @param {Number} index 로드된 탭 index
 * @param {String} userTabId w2:tabs id
 * @returns
 * @hidden N
 */
scwin.tab_ListCls_ontabload = async function (tabId, index, userTabId) {
    try {
        if (index === 0) {
            scwin.applyIsuColumns("");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.tab_ListCls_ontabload" });
    }
};

/**
 * @method
 * @name scwin.grd_MktList_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 시장조치 행 클릭 — 하위 탭이 전송내역이면 조치내역으로 바꾼다. (원본 grd_MktList OnClick — §4)
 * @param {Number} row 행 index
 * @param {Number} col 컬럼 index
 * @param {String} colId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_MktList_oncellclick = async function (row, col, colId) {
    try {
        if (Number(tab_ListCls.getSelectedTabIndex()) === 1) {
            tab_ListCls.setSelectedTabIndex(0);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.grd_MktList_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.grd_MktList_onrowindexchange
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 시장조치 행 이동 — 열 구성을 바꾸고 그 시장조치의 종목정보를 조회한다. (원본 dts_MktList OnRowPosChanged, processGp 1 — §6.1)
 * @param {Number} row 새 행 index
 * @param {Number} oldRow 이전 행 index
 * @returns
 * @hidden N
 */
scwin.grd_MktList_onrowindexchange = async function (row, oldRow) {
    try {
        if (row < 0) return;
        await scwin.selectClsMkt(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.grd_MktList_onrowindexchange" });
    }
};

/**
 * @method
 * @name scwin.grd_SendList_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 전송내역 행 클릭 — 그 종목의 시장조치내역을 조회한다. (원본 grd_SendList OnClick — §5.7)
 * @param {Number} row 행 index
 * @param {Number} col 컬럼 index
 * @param {String} colId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_SendList_oncellclick = async function (row, col, colId) {
    try {
        dlt_bndListingCloseMktackDtl.removeAll();
        await scwin.searchMktackDtl(dlt_bndListingCloseClsEndSendInfo.getCellData(row, "stdCd"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.grd_SendList_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 전송내역 엑셀다운로드 (원본 btn_Excel onclick — §6.6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Excel_onclick = async function (e) {
    try {
        scwin.excelDown(grd_SendList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ReClsProcs_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [재마감처리] 클릭 (원본 btn_ReClsProcs onclick → fn_ReClsProcs — §6.10)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ReClsProcs_onclick = async function (e) {
    try {
        await scwin.reClsProcs();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.btn_ReClsProcs_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_SendCfm_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [시장조치내역생성] 클릭 (원본 btn_SendCfm onclick → fn_SendCfm — §6.8)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_SendCfm_onclick = async function (e) {
    try {
        await scwin.sendCfm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.btn_SendCfm_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ClsProcs_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 클릭 — 팀장 권한 확인 후 마감 처리. (원본 btn_ClsProcs onclick → fn_ClsProcs — §6.9)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ClsProcs_onclick = async function (e) {
    try {
        // 직책 03(담당자)이면서 직무·직무담당이 모두 N 이면 막는다 (원본 js_jobtitl·js_duty·js_duty_chrg)
        const jobtitl = String($c.session.getUserInfo("jobtitl") ?? "");
        const duty = String($c.session.getUserInfo("duty") ?? "");
        const dutyChrg = String($c.session.getUserInfo("dutyChrg") ?? "");
        if (jobtitl === "03" && duty === "N" && dutyChrg === "N") {
            await $c.win.alert("팀장권한만 가능합니다.");
            return;
        }
        await scwin.clsProcs();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS30300.btn_ClsProcs_onclick" });
    }
};

