/**
 * @method
 * @name scwin.searchClsDd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 마감일 데이터 조회 → dma_bndListingCloseDd. (원본 fn_SearchClsDd(clsDd) — §5.1)
 * @param {String} clsDd 기준일 — [상장마감] 은 빈 값(서버가 현재 마감일), [상장마감내역] 은 업무마감일
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.searchClsDd = async function (clsDd) {
    const sbmOptions = {
        id : "sbm_searchClsDd",
        method : "get",
        action : "/api/bonds/bndCloseMgt/bndListingClose/bndListingCloseDd-select",
        ref : "",
        target : "dma_bndListingCloseDd=body",     // 명세 submission target 은 dlt_bndListingCloseDd — 정의는 dataMap(§10 #2)
        isProcessMsg : false
    };
    dma_bndListingCloseDd.setEmptyValue();
    // TODO: 명세는 ref: dma_search 와 requestData 를 함께 적음 — requestData 로 보낸다고 가정 (§10 #1)
    const result = await $c.sbm.executeDynamic(sbmOptions, scwin.getSearchData({ strtDd : clsDd }));
    if (result?.skipped) return false;
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.searchCls
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 시장조치별 종목수 조회 → 머리글 건수 → 첫 행 종목정보. (원본 fn_SearchCls + dts_MktList OnLoadCompleted/OnLoadError — §5.2)
 * @returns
 * @hidden N
 */
scwin.searchCls = async function () {
    const sbmOptions = {
        id : "sbm_searchCls",
        method : "get",
        action : "/api/bonds/bndCloseMgt/bndListingClose/bndListingCloseClsList-select",
        ref : "",
        target : "dlt_bndListingCloseClsList=body",
        gridview : "grd_MktList",
        isProcessMsg : false
    };
    const reqData = scwin.getSearchData({ strtDd : dma_screen.get("strtDd"), clsDd : dma_screen.get("prsntDd") });
    const result = await $c.sbm.executeDynamic(sbmOptions, reqData);
    if (result?.skipped) return;
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        return;
    }

    const cnt = dlt_bndListingCloseClsList.getRowCount();
    if (cnt === 0) {
        dlt_bndListingCloseClsDtl.removeAll();
        grd_MktList.setHeaderValue("h_bndMktactTpNm", "총 0 건");    // 원본 그대로 — 0건이면 "마감전 :" 없이 표시(§8 #10)
        return;
    }
    grd_MktList.setHeaderValue("h_bndMktactTpNm", "마감전 : 총 " + dlt_bndListingCloseClsList.getCellData(0, "totMktactCnt") + "건");

    // 원본은 데이터셋 로딩 때 OnRowPosChanged 가 첫 행으로 자동 발화했다 → 첫 행을 선택하고 종목정보를 직접 조회한다.
    // TODO: setFocusedCell 이 onrowindexchange 를 발화하면 두 번 조회하지만 종목정보 조회는 onDuplicate "abort" 라 마지막 것만 남는다 (§10 #14)
    grd_MktList.setFocusedCell(0, "bndMktactTpNm");
    await scwin.selectClsMkt(0);
};

/**
 * @method
 * @name scwin.searchClsDtl
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 시장조치의 종목정보 조회. (원본 fn_SearchClsDtl, processGp 1 — fn_GetQryId 로 시장조치코드별 queryId — §5.3)
 * @param {String} mktCd 채권시장조치구분코드
 * @returns
 * @hidden N
 */
scwin.searchClsDtl = async function (mktCd) {
    const sbmOptions = {
        id : "sbm_searchClsDtl",
        method : "get",
        action : "/api/bonds/bndCloseMgt/bndListingClose/bndListingCloseClsDtl-select",
        ref : "",
        target : "dlt_bndListingCloseClsDtl=body",
        gridview : "grd_IsuList",
        isProcessMsg : false
    };
    // TODO: 원본은 시장조치코드별로 queryId(listClsIsuInfo{코드})를 골랐다 — 명세는 경로 하나 + bndMktactTpCd. 서버 분기 확인 (§10 #4)
    // TODO: 명세 응답(dlt_searchTotList 24열)이 다른 화면(ULDBNS30400) 정의의 복사로 보여 AS-IS 열(45열) camelCase 로 정의함 (§10 #3)
    const reqData = scwin.getSearchData({ bndMktactTpCd : mktCd, strtDd : dma_screen.get("strtDd"), clsDd : dma_screen.get("prsntDd") });
    let result;
    try {
        result = await $c.sbm.executeDynamic(sbmOptions, reqData, null, { onDuplicate : "abort" });
    } catch (ex) {
        if (ex?.aborted) return;    // 행을 빠르게 옮겨 이전 조회가 취소됨 — 마지막 행이 이긴다
        throw ex;
    }
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));    // 원본 dts_IsuList OnLoadError
    }
};

/**
 * @method
