        isProcessMsg : false
    };
    const result = await $c.sbm.executeDynamic(sbmOptions, scwin.getSearchData({ strtDd : scwin.endClsDd }));
    if (result?.skipped) return;
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        return;
    }

    const cnt = dlt_bndListingCloseClsEnd.getRowCount();
    if (cnt === 0) {
        dlt_bndListingCloseClsEndDtl.removeAll();
        grd_MktList1.setHeaderValue("h_bndMktactTpNm", "총 0 건");
    } else {
        grd_MktList1.setHeaderValue("h_bndMktactTpNm", "총 " + dlt_bndListingCloseClsEnd.getCellData(0, "totMktactCnt") + "건");
    }

    // 원본: 0건이어도 전송정보는 조회한다 (dts_MktList OnLoadCompleted 끝의 fn_SearchSendIsuInfo)
    await scwin.searchClsSendInfo();

    if (cnt > 0) {
        // TODO: setFocusedCell 의 onrowindexchange 발화 여부 실측 (§10 #14)
        grd_MktList1.setFocusedCell(0, "bndMktactTpNm");
        await scwin.selectClsEndMkt(0);
    }
};

/**
 * @method
 * @name scwin.searchClsEndDtl
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감내역] 시장조치의 마감 종목정보 조회. (원본 fn_SearchClsDtl, processGp 2 — fn_GetQryIdEnd — §5.6)
 * @param {String} mktCd 채권시장조치구분코드
 * @returns
 * @hidden N
 */
scwin.searchClsEndDtl = async function (mktCd) {
    const sbmOptions = {
        id : "sbm_searchClsEndDtl",
        method : "get",
        action : "/api/bonds/bndCloseMgt/bndListingClose/bndListingCloseClsEndDtl-select",
        ref : "",
        target : "dlt_bndListingCloseClsEndDtl=body",
        gridview : "grd_IsuList1",
        isProcessMsg : false
    };
    // TODO: 원본 fn_GetQryIdEnd 의 코드별 queryId(500·900·314·신규상장군·기본)를 서버가 bndMktactTpCd 로 가르는지 확인 (§10 #4)
    // TODO: 명세 응답(dlt_searchPackListIsuList 24열)은 다른 화면 정의의 복사로 보임 — 그리드 3열 + 팝업용 strtDd 로 정의 (§10 #3)
    const reqData = scwin.getSearchData({ bndMktactTpCd : mktCd, strtDd : scwin.endClsDd });
    let result;
    try {
        result = await $c.sbm.executeDynamic(sbmOptions, reqData, null, { onDuplicate : "abort" });
    } catch (ex) {
        if (ex?.aborted) return;
        throw ex;
    }
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
};

