/**
 * @method
 * @name scwin.getSearchData
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회 요청 데이터 — 명세 requestData 8키를 모두 채우고, 이 호출에서 쓰는 값만 넣는다(나머지는 빈 값). (§6.13)
 * @param {Object} values 넣을 값 { strtDd, clsDd, bndMktactTpCd, applYn, stdCd, isurCd, taskDd }
 * @returns {Object} dma_search JSON
 * @hidden N
 */
scwin.getSearchData = function (values) {
    dma_search.setEmptyValue();
    dma_search.set("empNo", String($c.session.getUserInfo("empNo") ?? ""));    // 명세 로그인사번 (원본은 세션으로 서버가 처리 — §10 #7)
    Object.keys(values ?? {}).forEach(function (key) {
        dma_search.set(key, values[key] ?? "");
    });
    return dma_search.getJSON();
};

/**
 * @method
 * @name scwin.setSaveData
 * @author Inswave
 * @date 2026. 10. 28
 * @description 처리(생성·마감·재마감) 요청 dma_save — 적용일·마감일(현재일)·로그인 사번/성명. (원본 Parameters "STRT_DD=…,CLS_DD=…" — §6.13)
 * @returns
 * @hidden N
 */
scwin.setSaveData = function () {
    dma_save.set("strtDd", dma_screen.get("strtDd"));
    dma_save.set("clsDd", dma_screen.get("prsntDd"));
    dma_save.set("empNo", String($c.session.getUserInfo("empNo") ?? ""));
    dma_save.set("empNm", String($c.session.getUserInfo("empNm") ?? ""));
};

/**
 * @method
 * @name scwin.afterProc
 * @author Inswave
 * @date 2026. 10. 28
 * @description 처리 결과 — 성공이면 MSG-0001 안내 후 [상장마감] 탭 재조회, 실패면 MSG-0002. (원본 trs_Save OnSuccess / OnFail — §5.11~§5.13)
 * @param {Object} result executeDynamic 결과
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.afterProc = async function (result) {
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
        return false;
    }
    await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    await scwin.loadClsTab();
    return true;
};

/**
 * @method
 * @name scwin.loadClsTab
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 탭 조회 — 마감일 → 현재일·적용일 → 전송내역 → 마감 상태 문구 → 시장조치별 종목수. 로딩·탭 복귀·처리 성공 뒤에 부른다. (원본 fn_SearchClsDd('') + dts_CheckCls OnLoadCompleted, processGp 1 — §6.1)
 * @returns
 * @hidden N
 */
scwin.loadClsTab = async function () {
    if (!await scwin.searchClsDd("")) return;

    // 업무마감일이 비었으면 현재일 ([상장마감내역] 탭 기본값 — 원본 첫 조회에서 채움)
    if ($c.util.isEmpty(dma_screen.get("bizClsDd"))) {
        dma_screen.set("bizClsDd", dma_bndListingCloseDd.get("prsntDd"));
    }
    dma_screen.set("prsntDd", dma_bndListingCloseDd.get("prsntDd"));
    dma_screen.set("strtDd", dma_bndListingCloseDd.get("clsDd"));

    await scwin.searchSendData();

    // 마감 상태 문구 (원본: readChkClsProc 동기 조회)
    if (await scwin.searchChkProc()) {
        if (dma_bndListingCloseChkProc.get("validBndCls") === "Y") {
            txb_ClsDtl.setValue(scwin.CLS_DTL_MSG.done);
        } else if (dma_bndListingCloseChkProc.get("validSendCfm") === "Y") {
            txb_ClsDtl.setValue(scwin.CLS_DTL_MSG.notDone);
            tab_ListCls.setSelectedTabIndex(1);    // 시장조치내역이 생성됐으면 전송내역 탭을 보여 준다
        } else {
            txb_ClsDtl.setValue(scwin.CLS_DTL_MSG.notDone);
        }
    }

    await scwin.searchCls();
};

/**
 * @method
 * @name scwin.selectClsMkt
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 시장조치 행 선택 — 종목정보를 비우고 열 구성을 바꾼 뒤, 종목수가 있으면 조회한다. (원본 dts_MktList OnRowPosChanged, processGp 1 — §6.1)
 * @param {Number} row 행 index
 * @returns
 * @hidden N
 */
scwin.selectClsMkt = async function (row) {
    dlt_bndListingCloseClsDtl.removeAll();
    const mktCd = dlt_bndListingCloseClsList.getCellData(row, "bndMktactTpCd");
    scwin.applyIsuColumns(mktCd);
    if (Number(dlt_bndListingCloseClsList.getCellData(row, "mktactCnt")) > 0) {
        await scwin.searchClsDtl(mktCd);
    }
};

/**
 * @method
 * @name scwin.searchClsEndTab
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감내역] 조회 — 업무마감일 확인 → 마감일 조회 → 업무마감일이 아니면 목록 비움, 맞으면 마감 종목수·전송내역 조회. (원본 btn_Search onclick + dts_CheckCls OnLoadCompleted, processGp 2 — §6.2)
 * @returns
 * @hidden N
 */
scwin.searchClsEndTab = async function () {
    const bizClsDd = dma_screen.get("bizClsDd");
    if ($c.util.isEmpty(bizClsDd)) {
        await $c.win.alert("업무마감일을 입력 하십시오.");
        edt_BizClsDd.focus();
        return;
    }
    if (!await scwin.searchClsDd(bizClsDd)) return;

    // 원본 키 이름 그대로 — validBizClsDd 가 "Y" 면 업무마감일이 아니다(§7.1)
    if (dma_bndListingCloseDd.get("validBizClsDd") === "Y") {
        await $c.win.alert("업무마감일이 아닙니다.");
        dlt_bndListingCloseClsEnd.removeAll();
        dlt_bndListingCloseClsEndSendInfo1.removeAll();
        dlt_bndListingCloseMktackDtl1.removeAll();
        dlt_bndListingCloseClsSendInfo.removeAll();
        dlt_bndListingCloseClsEndDtl.removeAll();
        grd_MktList1.setHeaderValue("h_bndMktactTpNm", "총 0 건");
        return;
    }
    scwin.endClsDd = dma_bndListingCloseDd.get("endClsDd");

    await scwin.searchClsEnd();
    await scwin.searchSendData1();
};

/**
 * @method
 * @name scwin.selectClsEndMkt
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감내역] 시장조치 행 선택 — 종목정보를 비우고 종목수가 있으면 조회한다. (원본 dts_MktList OnRowPosChanged, processGp 2 — §6.2)
 * @param {Number} row 행 index
 * @returns
 * @hidden N
 */
scwin.selectClsEndMkt = async function (row) {
    dlt_bndListingCloseClsEndDtl.removeAll();
    const mktCd = dlt_bndListingCloseClsEnd.getCellData(row, "bndMktactTpCd");
    if (Number(dlt_bndListingCloseClsEnd.getCellData(row, "mktactCnt")) > 0) {
        await scwin.searchClsEndDtl(mktCd);
    }
};

/**
 * @method
 * @name scwin.applyIsuColumns
 * @author Inswave
 * @date 2026. 10. 28
 * @description [상장마감] 조치내역 종목정보 열 구성 — 모든 토글 열을 숨기고 머리글을 기본 문구로 되돌린 뒤 시장조치코드의 열만 보인다. (원본 fn_IntiIsuCol + fn_showFalse + fn_show* — §6.3)
 * @param {String} mktCd 채권시장조치구분코드 (빈 값이면 기본 열)
 * @returns
 * @hidden N
 */
scwin.applyIsuColumns = function (mktCd) {
    const showCols = scwin.ISU_COLS_BY_MKT[mktCd] ?? scwin.ISU_COLS_BY_MKT["default"];
    scwin.ISU_TOGGLE_COLS.forEach(function (colId) {
        grd_IsuList.setColumnVisible(colId, showCols.indexOf(colId) > -1);
    });
    const headers = Object.assign({}, scwin.ISU_HEADER_DEFAULT, scwin.ISU_HEADER_BY_MKT[mktCd] ?? {});
    Object.keys(headers).forEach(function (colId) {
        grd_IsuList.setHeaderValue("h_" + colId, headers[colId]);
    });
};

/**
 * @method
 * @name scwin.sendCfm
 * @author Inswave
 * @date 2026. 10. 28
 * @description 시장조치내역생성 — 완성형한글 체크 → 처리 전 체크(마감 종료·데이터 문제·신용등급·스트립) → 종목중복 체크 → 확인 → 생성. (원본 fn_SendCfm — §6.8)
 * @returns
 * @hidden N
 */
scwin.sendCfm = async function () {
    // 1) 완성형 한글 체크 — 문제 데이터가 있으면 계속할지 묻는다
    if (!await scwin.searchKorChk()) return;
    // TODO: 원본은 결과 행 수(CountRow > 0)로 판정했다 — 명세 응답은 dataMap 이라 div 값 유무로 판정한다 (§10 #8)
    const korDiv = dma_bndListingCloseKorChk.get("div");
    if (!$c.util.isEmpty(korDiv)) {
        let msg = "";
        if (korDiv === "1") {
            msg += " 금일 발행기관 데이터에 문제가 있습니다.";
            msg += "\n\n 문제발생 발행기관코드 : " + dma_bndListingCloseKorChk.get("isurCd");
            msg += "\n 문제발생 발행기관명 : " + dma_bndListingCloseKorChk.get("comNm");
        } else if (korDiv === "2") {
            msg += "금일 채권마스터 데이터에 문제가 있습니다.";
            msg += "\n\n 문제발생 표준코드 : " + dma_bndListingCloseKorChk.get("isurCd");
            msg += "\n 문제발생 한글종목명 : " + dma_bndListingCloseKorChk.get("comNm");
        }
        msg += "\n\n 시스템담당자에게 연락바랍니다.";
        msg += "\n\n 계속 진행하시겠습니까?";
        if (!await $c.win.confirm(msg)) return;
    }

    // 2) 처리 전 체크
    if (!await scwin.searchChkProc()) return;
    const chk = dma_bndListingCloseChkProc;
    if (chk.get("validBndCls") === "Y") {
        await $c.win.alert("업무마감작업이 이미 종료되었습니다.");
        return;
    }
    // 발행기관·채권마스터·신청마스터 종목명에 엔터값이 있는지
    const isurCd = chk.get("isurCd") ?? "";
    const stdCd = chk.get("stdCd") ?? "";
    const stdCdAppl = chk.get("stdCdAppl") ?? "";
    if (isurCd !== "" || stdCd !== "" || stdCdAppl !== "") {
        let msg = "금일 발행기관, 채권마스터 데이터에 문제가 있습니다.";
        msg += "\n 문제발생 발행기관코드 : " + isurCd;
        msg += "\n 문제발생 채권마스터코드 : " + stdCd;
        msg += "\n 문제발생 신청마스터코드 : " + stdCdAppl;
        msg += "\n 시스템담당자에게 연락바랍니다.";
        await $c.win.alert(msg);
        return;
    }
    // 금일 수신된 신용등급정보 처리 여부
    if (chk.get("hasCreditRcv") === "Y" && chk.get("validCreditRcv") === "Y") {
        await $c.win.alert("금일 수신된 신용등급정보를 처리하지 않았습니다.\n 신용평가 수신내역을 확인바랍니다.");
        return;
    }
    // 스트립 통합처리 완료 여부
    if (chk.get("validStrip") === "Y") {
        await $c.win.alert("마감처리 전 스트립 통합처리를 하시기 바랍니다.");
        return;
    }
    if (chk.get("validStrip") === "F") {
        await $c.win.alert("스트립 시장조치(스트립신규, 추가 및 재결합)와\n\n'스트립 통합처리' 화면내용이 불일치함.\n\n'스트립 통합처리'를 취소 후 다시 진행바람.");
        return;
    }

    // 3) 미처리건 확인 (원본 2026.01.05 추가 — listCheckNotComplt)
    // TODO: 명세에 미처리건 조회 API 가 없어 이 확인을 건너뛴다 — 명세를 받으면 "미처리건이 존재합니다. 계속하시겠습니까?" + 시장조치별 건수 확인을 넣는다 (§10 #9, 배포 전 확인)

    // 4) 종목중복 체크
    if (!await scwin.searchDupIsu()) return;
    const dupCnt = dlt_bndListingCloseDupIsu.getRowCount();
    if (dupCnt > 0) {
        let dupMsg = "";
        for (let i = 0; i < dupCnt; i++) {
            dupMsg += dlt_bndListingCloseDupIsu.getCellData(i, "dupIsu") + "\n";
        }
        dupMsg += "로 중복조치되었습니다.\n확인 후 다시 처리하여 주십시오.";
        await $c.win.alert(dupMsg);
        return;
    }

    // 5) 확인 → 생성
    if (!await $c.win.confirm($c.stf.getMessageParam("MSG-A006", "시장조치내역생성"))) return;
    await scwin.procSend();
};

/**
 * @method
 * @name scwin.clsProcs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장마감 — 처리 전 체크(시장조치내역 생성 여부·업무마감 종료) → 확인 → 마감. (원본 fn_ClsProcs — §6.9)
 * @returns
 * @hidden N
 */
scwin.clsProcs = async function () {
    if (!await scwin.searchChkProc()) return;
    if (dma_bndListingCloseChkProc.get("validSendCfm") !== "Y") {
        await $c.win.alert("시장조치내역생성 처리를 하십시오.");
        return;
    }
    if (dma_bndListingCloseChkProc.get("validBndCls") === "Y") {
        await $c.win.alert("업무마감작업이 이미 종료되었습니다.");
        return;
    }
    if (!await $c.win.confirm($c.stf.getMessageParam("MSG-A006", "상장마감"))) return;
    await scwin.procCls();
};

/**
 * @method
 * @name scwin.reClsProcs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 재마감처리 — 처리 전 체크(일일 시장조치반영 완료면 불가, 업무마감 전이면 불가) → 삭제 대상 안내 → 확인 → 전송내역 비움 → 재마감. (원본 fn_ReClsProcs — §6.10)
 * @returns
 * @hidden N
 */
scwin.reClsProcs = async function () {
    if (!await scwin.searchChkProc()) return;
    if (dma_bndListingCloseChkProc.get("validBndCls1") === "Y") {
        await $c.win.alert("이미 일일 시장조치반영이 완료 되었습니다.");
        return;
    }
    if (dma_bndListingCloseChkProc.get("validBndCls") === "Y") {
        let msg = "채권송신(매매)데이타를 다시 생성하여 송신 할 경우에 해당합니다.";
        msg += "\n다음 데이타가 클리어(Delete)됩니다.";
        msg += "\n- 채권마감이력";
        msg += "\n- 시장조치 전송내역";
        msg += "\n- 신용평가 전송내역";
        await $c.win.alert(msg);
    } else {
        await $c.win.alert("업무마감이 되지 않아 업무마감처리를\n다시 하실수 없습니다.");
        return;
    }
    if (!await $c.win.confirm($c.stf.getMessageParam("MSG-A006", "재마감처리"))) return;
    dlt_bndListingCloseClsEndSendInfo.removeAll();
    dlt_bndListingCloseMktackDtl.removeAll();
    await scwin.procReCls();
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 28
 * @description 전송내역(송신시장조치) 엑셀 다운로드. 0건 안내는 공통 함수가 한다. (원본 GridToExcel('', 적용일_시장조치내역, '8') — §6.6)
 * @param {Object} grd 대상 그리드(grd_SendList / grd_SendList1)
 * @returns
 * @hidden N
 */
scwin.excelDown = function (grd) {
    // TODO: 원본 GridToExcel 옵션 '8' 의 의미(숨김 열·서식) 확인 (§10 #12)
    $c.data.downloadGridViewExcel(grd, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42) — 원본 파일명의 적용일 접두는 쓰지 않는다(§8 #13)
        fileName : $c.win.getProgramId() + "_시장조치내역_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};

/**
 * @method
 * @name scwin.openMktFilePopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 시장지파일 팝업(ULDBNS30301) — 업무마감일을 매매일자로 넘긴다. (원본 fn_GetParMktFile + fn_PopMktFile — §6.11)
 * @returns
 * @hidden N
 */
scwin.openMktFilePopup = async function () {
    const options = {
        id : "ULDBNS30301",
        type : "pageFramePopup",
        popupName : "시장지파일",
        modal : true,
        width : 550,
        height : 400
    };
    // pcc $c.bns.popMktFile(trdDd) 는 data 를 넘기지 않아 화면에서 직접 연다(URL·크기는 pcc 와 같음).
    // TODO: ULDBNS30301 은 아직 fn_GetPar(arr[0].TRD_DD) 수신 1차본 — getParameter().trdDd 로 전환 전에는 빈 매매일자로 열림 (§10 #10, 배포 전 차단)
    await $c.win.openPopup("/ui/bns/bnscls/ULDBNS30301.xml", options, { trdDd : dma_screen.get("bizClsDd") });
};

/**
 * @method
 * @name scwin.openIsuDtlPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목상세정보 팝업(ULDBNS25102) — 더블클릭한 종목의 표준코드·적용일을 넘긴다. (원본 fn_GetParIsuDtlAndMktactDtl + fn_PopIsuDtlAndMktactDtl — §6.12)
 * @param {Number} row 더블클릭한 행 index
 * @returns
 * @hidden N
 */
scwin.openIsuDtlPopup = async function (row) {
    const data = {
        stdCd : dlt_bndListingCloseClsEndDtl.getCellData(row, "stdCd"),     // 원본 arr[0].STD_CD
        strtDd : dlt_bndListingCloseClsEndDtl.getCellData(row, "strtDd")    // 원본 arr[0].STRT_DD (응답 키 가정 §10 #3)
    };
    const options = {
        id : "ULDBNS25102",
        type : "pageFramePopup",
        popupName : "종목상세정보",
        modal : true,
        width : 1250,
        height : 750
    };
    // pcc $c.bns.popIsuDtlAndMktactDtl(grdObj) 는 data 를 넘기지 않아 화면에서 직접 연다.
    // TODO: ULDBNS25102 는 아직 fn_GetPar 수신 1차본 — getParameter() 로 전환 전에는 빈 화면으로 열림 (§10 #10, 배포 전 차단)
    await $c.win.openPopup("/ui/bns/bnslistsrchl/ULDBNS25102.xml", options, data);
};
